create table xxventuri.visitor_access_t (
    visitor_id        number,
    name_of_person    varchar2(100 byte) not null enable,
    organization_name varchar2(150 byte),
    mobile_number     varchar2(15 byte) not null enable,
    email             varchar2(150 byte),
    validity_from     date not null enable,
    validity_to       date not null enable,
    purpose           varchar2(500 byte),
    shop_floor_access varchar2(100 byte),
    upload_file_name  varchar2(255 byte),
    upload_mime_type  varchar2(100 byte),
    upload_blob       blob,
    created_by        varchar2(100 byte),
    created_on        date,
    updated_by        varchar2(100 byte),
    updated_on        date,
    envelope_id       varchar2(255 byte)
);

alter table xxventuri.visitor_access_t
    add constraint visitor_access_pk primary key ( visitor_id )
        using index enable;


